import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from '@google/genai';
import { ChatMessage } from '../types';

export const GeminiChat: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: '你好！我是吴思洁的 AI 作品集助手。很高兴能协助你了解她的学术背景和项目。' }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;
    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMsg,
        config: {
          systemInstruction: `
            You are an AI assistant for Sijie WU (吴思洁)'s portfolio. 
            Background Information:
            - Education: Currently a MA candidate at Columbia University TC (GPA 4.0), BEd from SHNU (GPA 3.64), Exchange at UC Irvine (GPA 4.0).
            - Professional Experiences: Snow Day Learning Lab, PhD Research Support (Scratch analysis), Oriental Kindergarten internship.
            - Projects: 
              1. Learning Synapse: AI-powered system for text-to-learning materials.
              2. Snap Story: ESL/EFL learning app using contextual inputs.
            - Skills: Instructional Design, Visual Design, Figma, Canva, AI Studio, Web Dev.
            Tone: Professional, friendly, artistic, and technologically savvy. Respond concisely in Chinese (or English if the user asks).
          `
        }
      });
      setMessages(prev => [...prev, { role: 'model', text: response.text || "Sorry, I couldn't process that." }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Connection error." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="fixed bottom-8 right-8 z-[60] w-14 h-14 rounded-full bg-sky-600 shadow-xl shadow-sky-200 flex items-center justify-center text-white hover:scale-110 active:scale-95 transition-all group"
      >
        <svg className="w-6 h-6 group-hover:rotate-12 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
        </svg>
      </button>

      <div className={`fixed bottom-28 right-8 z-[60] w-[350px] md:w-[400px] h-[550px] glass-card shadow-2xl transition-all duration-500 origin-bottom-right flex flex-col ${isOpen ? 'scale-100 opacity-100' : 'scale-0 opacity-0 pointer-events-none'}`}>
        <div className="p-6 border-b border-sky-100 flex items-center justify-between bg-sky-50/50 rounded-t-[32px]">
          <div>
            <h3 className="font-black text-sky-900 font-heading">AI Assistant</h3>
            <p className="text-[10px] text-sky-500 font-bold uppercase tracking-widest">Sijie's Digital Proxy</p>
          </div>
          <button onClick={() => setIsOpen(false)} className="text-slate-400 hover:text-sky-600 transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-4">
          {messages.map((m, idx) => (
            <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-4 rounded-[20px] text-sm leading-relaxed ${m.role === 'user' ? 'bg-sky-600 text-white shadow-md' : 'bg-white text-slate-600 shadow-sm border border-sky-50'}`}>
                {m.text}
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-white p-4 rounded-[20px] shadow-sm flex gap-1 items-center">
                <div className="w-1 h-1 rounded-full bg-sky-400 animate-bounce"></div>
                <div className="w-1 h-1 rounded-full bg-sky-400 animate-bounce delay-100"></div>
                <div className="w-1 h-1 rounded-full bg-sky-400 animate-bounce delay-200"></div>
              </div>
            </div>
          )}
        </div>

        <div className="p-6 bg-sky-50/30 rounded-b-[32px]">
          <div className="relative">
            <input 
              type="text" 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="询问她的背景..."
              className="w-full bg-white border border-sky-100 rounded-2xl px-5 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-sky-200 transition-all shadow-sm"
            />
            <button 
              onClick={handleSend}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-sky-600 hover:scale-110 transition-transform"
            >
              <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
              </svg>
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

