              isYouTube(project.videoUrl) ? (
                <iframe
                  className="absolute inset-0 w-full h-full z-10"
                  src={`https://www.youtube-nocookie.com/embed/${getYouTubeId(project.videoUrl)}?autoplay=1&rel=0&modestbranding=1`}
                  title={project.title}
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                  referrerPolicy="no-referrer"
                ></iframe>
              ) : (
                <video 
                  src={project.videoUrl} 
                  autoPlay 
                  controls 
                  className="absolute inset-0 w-full h-full object-cover z-10"
                />
              )
            ) : (
              <div 
                className="absolute inset-0 w-full h-full cursor-pointer"
                onClick={() => setPlayingId(project.id)}
              >
                <img 
                  src={project.placeholderImg} 
                  alt={project.title} 
                  className="w-full h-full object-cover opacity-70 group-hover:opacity-50 transition-all duration-700 group-hover:scale-105" 
                />

