interface ProjectsProps {
  projects: Project[];
}

export const Projects: React.FC<ProjectsProps> = ({ projects }) => {
  const [playingId, setPlayingId] = useState<string | null>(null);
  // 使用随机 key 强制 iframe 在重试时重新渲染
  const [playerKey, setPlayerKey] = useState(0);

  const handlePlay = (id: string) => {
    setPlayerKey(prev => prev + 1);
    setPlayingId(id);
  };

  const isYouTube = (url?: string) => url?.includes('youtube.com') || url?.includes('embed');

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-10 lg:gap-16">
      {projects.map((project) => (
        <div key={project.id} className="flex flex-col reveal">
          {/* 视频容器 */}
          <div 
            className={`relative w-full overflow-hidden rounded-[40px] border shadow-2xl bg-black group transition-all duration-500 ${
              project.id === 'learning-synapse' ? 'border-sky-500/20' : 'border-white/10'
            }`}
            style={{ aspectRatio: '16 / 9' }}
          >
            {/* 播放状态渲染 */}
            {playingId === project.id && project.videoUrl ? (
              isYouTube(project.videoUrl) ? (
                <iframe
                  key={`${project.id}-${playerKey}`}
                  className="absolute inset-0 w-full h-full z-10"
                  src={`${project.videoUrl}?autoplay=1&mute=0&rel=0&modestbranding=1&enablejsapi=1`}
                  title={project.title}
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                  referrerPolicy="no-referrer"
                  sandbox="allow-forms allow-scripts allow-pointer-lock allow-same-origin allow-top-navigation allow-presentation"
                ></iframe>
              ) : (
                <video 
                  src={project.videoUrl} 
                  autoPlay 
                  controls 
                  className="absolute inset-0 w-full h-full object-cover z-10"
                />
              )
            ) : (
              <div 
                className="absolute inset-0 w-full h-full cursor-pointer overflow-hidden"
                onClick={() => handlePlay(project.id)}
              >
                <img 
                  src={project.placeholderImg} 
                  alt={project.title} 
                  className="w-full h-full object-cover opacity-80 group-hover:opacity-40 transition-all duration-1000 group-hover:scale-110" 
                />

                {/* 居中播放按钮 */}
                <div className="absolute inset-0 flex items-center justify-center z-20">
                  <div className="w-24 h-24 bg-white/10 backdrop-blur-3xl border border-white/30 rounded-full flex items-center justify-center group-hover:scale-110 group-hover:bg-sky-500 group-hover:border-sky-400 transition-all duration-500 shadow-[0_0_50px_rgba(14,165,233,0.3)]">
                    <svg className="w-10 h-10 text-white translate-x-1" fill="currentColor" viewBox="0 0 24 24">
                      <path d="M8 5v14l11-7z" />
                    </svg>
                  </div>
                </div>

                {/* 文字提示 */}
                <div className="absolute bottom-10 left-10 z-20">
                  <div className="bg-black/20 backdrop-blur-xl px-6 py-2.5 rounded-2xl border border-white/10">
                    <p className="text-[11px] font-black text-white uppercase tracking-[0.3em]">Watch Project Demo</p>
                  </div>
                </div>
              </div>
            )}

            {/* 悬浮跳转按钮：万一 YouTube 依然报错，用户可以点击这里直接去原站 */}
            {project.id === 'learning-synapse' && (
              <a 
                href="https://www.youtube.com/watch?v=j3_AmdPbkNQ" 
                target="_blank" 
                rel="noopener noreferrer"
                onClick={(e) => e.stopPropagation()}
                className="absolute top-6 right-6 z-30 flex items-center gap-3 bg-red-600 hover:bg-red-700 text-white px-5 py-3 rounded-2xl shadow-2xl transition-all hover:scale-105 active:scale-95 group/btn"
              >
                <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M23.498 6.186a3.016 3.016 0 0 0-2.122-2.136C19.505 3.545 12 3.545 12 3.545s-7.505 0-9.377.505A3.017 3.017 0 0 0 .502 6.186C0 8.07 0 12 0 12s0 3.93.502 5.814a3.016 3.016 0 0 0 2.122 2.136c1.871.505 9.376.505 9.376.505s7.505 0 9.377-.505a3.015 3.015 0 0 0 2.122-2.136C24 15.93 24 12 24 12s0-3.93-.502-5.814zM9.545 15.568V8.432L15.818 12l-6.273 3.568z"/>
                </svg>
                <span className="text-[10px] font-black uppercase tracking-widest">YouTube 直达</span>
              </a>
            )}
          </div>

          {/* 项目详情部分 */}
          <div className="px-2 mt-10">
            <div className="flex items-center gap-4 mb-8">
              <span className="text-[11px] font-black text-sky-500 tracking-[0.2em] uppercase bg-sky-50 px-4 py-1.5 rounded-xl border border-sky-100 shadow-sm">
                {project.category}
              </span>
              <div className="h-[1px] flex-1 bg-gradient-to-r from-slate-100 to-transparent"></div>
            </div>

            <h3 className="text-4xl font-black font-heading text-slate-900 mb-6 tracking-tight">{project.title}</h3>

            <p className="text-slate-500 text-xl font-light leading-relaxed mb-10 max-w-xl">
              {project.description}
            </p>

            <div className="flex flex-wrap gap-3 mb-10">
              {project.tech.map(t => (
                <span key={t} className="px-5 py-2 rounded-2xl border border-slate-100 text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-white shadow-sm hover:border-sky-200 hover:text-sky-400 transition-colors">
                  {t}
                </span>
              ))}
            </div>

            <div className="flex items-center gap-8">
              <a 
                href={project.liveDemo} 
                target="_blank" 
                rel="noopener noreferrer"
                className="group inline-flex items-center gap-3 text-[12px] font-black tracking-[0.2em] uppercase text-sky-500 transition-all"
