interface ProjectsProps {
  projects: Project[];
}

export const Projects: React.FC<ProjectsProps> = ({ projects }) => {
  const [playingId, setPlayingId] = useState<string | null>(null);

  const isYouTube = (url?: string) => url?.includes('youtube') || url?.includes('embed') || url?.includes('shorts');
  const isVimeo = (url?: string) => url?.includes('vimeo');

  const getYouTubeId = (url: string) => {
    const match = url.match(/(?:embed\/|v\/|watch\?v=|youtu\.be\/|shorts\/)([^#&?]*)/);
    return (match && match[1].length === 11) ? match[1] : null;
  };

  const getVimeoId = (url: string) => {
    const match = url.match(/vimeo\.com\/(?:video\/|)(\d+)/);
    return (match && match[1]) ? match[1] : null;
  };

  const getEmbedUrl = (url: string) => {
    if (isYouTube(url)) {
      const id = getYouTubeId(url);
      // 移除强制静音 mute=1 以避免出现浏览器的“取消静音”覆盖层
      return id ? `https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0&modestbranding=1` : url;
    }
    if (isVimeo(url)) {
      const id = getVimeoId(url);
      // Vimeo 不强制静音，由用户手动控制或浏览器自适应
      return id ? `https://player.vimeo.com/video/${id}?autoplay=1&badge=0&autopause=0&player_id=0&app_id=58479` : url;
    }
    return url;
  };

  const toggleFullscreen = (id: string) => {
    const el = document.getElementById(`container-${id}`);
    if (el) {
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else {
        el.requestFullscreen().catch(err => console.error(err));
      }
    }
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-10 lg:gap-16 items-start">
      {projects.map((project) => (
        <div key={project.id} className="flex flex-col reveal">
          {/* 视频核心容器 */}
          <div 
            id={`container-${project.id}`}
            className={`relative w-full overflow-hidden rounded-[40px] border shadow-2xl bg-black group transition-all duration-700 ${
              project.id === 'learning-synapse' ? 'border-sky-500/20' : 'border-white/10'
            }`}
            style={{ 
              aspectRatio: project.id === 'snap-story' ? '9 / 16' : '16 / 9',
              maxHeight: project.id === 'snap-story' ? '800px' : 'none'
            }}
          >
            {/* 播放中状态 */}
            {playingId === project.id && project.videoUrl ? (
              <div className="absolute inset-0 w-full h-full bg-black">
                {isYouTube(project.videoUrl) || isVimeo(project.videoUrl) ? (
                  <iframe
                    className="absolute inset-0 w-full h-full z-10"
                    src={getEmbedUrl(project.videoUrl)}
                    title={project.title}
                    frameBorder="0"
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share; fullscreen"
                    referrerPolicy="strict-origin-when-cross-origin"
                    allowFullScreen
                  ></iframe>
                ) : (
                  <video 
                    src={project.videoUrl} 
                    autoPlay 
                    controls 
                    playsInline
                    className="absolute inset-0 w-full h-full object-cover z-10"
                  />
                )}

                {/* 极其精致的顶部悬浮栏 */}
                <div className="absolute top-4 left-4 right-4 z-20 flex justify-between items-center pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-500">
                  <div className="flex gap-2 pointer-events-auto">
                    <button 
                      onClick={() => setPlayingId(null)}
                      className="bg-white/10 hover:bg-white/30 backdrop-blur-md text-white text-[8px] font-black px-3 py-1.5 rounded-full transition-all border border-white/10 uppercase tracking-[0.2em]"
                    >
                      Close
                    </button>
                    <button 
                      onClick={() => toggleFullscreen(project.id)}
                      className="bg-white/10 hover:bg-white/30 backdrop-blur-md text-white text-[8px] font-black px-3 py-1.5 rounded-full transition-all border border-white/10 uppercase tracking-[0.2em]"
                    >
                      Expand
                    </button>
                  </div>

                  <a 
                    href={project.videoUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="pointer-events-auto bg-white/10 hover:bg-white/30 backdrop-blur-md text-white text-[8px] font-black px-3 py-1.5 rounded-full transition-all border border-white/10 uppercase tracking-[0.2em]"
                  >
                    View Link
                  </a>
                </div>
              </div>
            ) : (
              /* 封面状态 */
              <div 
                className="absolute inset-0 w-full h-full cursor-pointer overflow-hidden"
                onClick={() => setPlayingId(project.id)}
              >
                <img 
                  src={project.placeholderImg} 
                  alt={project.title} 
                  className="w-full h-full object-cover opacity-80 group-hover:opacity-40 transition-all duration-700 group-hover:scale-105" 
                />

                {/* 播放按钮 */}
                <div className="absolute inset-0 flex items-center justify-center z-20">
                  <div className="w-20 h-20 md:w-24 md:h-24 bg-white/10 backdrop-blur-3xl border border-white/30 rounded-full flex items-center justify-center group-hover:scale-110 group-hover:bg-sky-500 group-hover:border-sky-400 transition-all duration-500 shadow-2xl">
                    <svg className="w-8 h-8 md:w-10 md:h-10 text-white translate-x-1" fill="currentColor" viewBox="0 0 24 24">
                      <path d="M8 5v14l11-7z" />
                    </svg>
                  </div>
                </div>

                {/* 提示信息 */}
                <div className="absolute bottom-10 left-1/2 -translate-x-1/2 md:left-10 md:translate-x-0 z-20">
                  <div className="bg-black/30 backdrop-blur-xl px-6 py-2.5 rounded-2xl border border-white/10">
                    <p className="text-[11px] font-black text-white uppercase tracking-[0.3em]">Play Preview</p>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* 项目介绍内容 */}
          <div className="px-2 mt-10">
            <div className="flex items-center gap-4 mb-8">
              <span className="text-[11px] font-black text-sky-500 tracking-[0.2em] uppercase bg-sky-50 px-4 py-1.5 rounded-xl border border-sky-100">
                {project.category}
              </span>
              <div className="h-[1px] flex-1 bg-slate-100"></div>
            </div>

            <h3 className="text-4xl font-black font-heading text-slate-900 mb-6 tracking-tight">{project.title}</h3>

            <p className="text-slate-500 text-xl font-light leading-relaxed mb-10">
              {project.description}
            </p>

            <div className="flex flex-wrap gap-3 mb-10">
              {project.tech.map(t => (
                <span key={t} className="px-5 py-2 rounded-2xl border border-slate-100 text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-white shadow-sm">
                  {t}
                </span>
              ))}
            </div>

            <div className="flex items-center gap-8">
              <a 
                href={project.liveDemo} 
                target="_blank" 
                rel="noopener noreferrer"
                className="group inline-flex items-center gap-3 text-[12px] font-black tracking-[0.2em] uppercase text-sky-500 transition-all"
              >
                Project Archive
                <div className="w-10 h-10 rounded-full border border-sky-100 flex items-center justify-center group-hover:bg-sky-500 group-hover:text-white transition-all">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M17 8l4 4m0 0l-4 4m4-4H3" /></svg>
                </div>
              </a>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

