import React, { useState } from 'react';
import { Project } from '../types';

interface ProjectsProps {
  projects: Project[];
}

export const Projects: React.FC<ProjectsProps> = ({ projects }) => {
  const [playingId, setPlayingId] = useState<string | null>(null);

  const isYouTube = (url?: string) => url?.includes('youtube') || url?.includes('embed') || url?.includes('shorts');
  const isVimeo = (url?: string) => url?.includes('vimeo');

  const getYouTubeId = (url: string) => {
    const match = url.match(/(?:embed\/|v\/|watch\?v=|youtu\.be\/|shorts\/)([^#&?]*)/);
    return (match && match[1].length === 11) ? match[1] : null;
  };

  const getVimeoId = (url: string) => {
    const match = url.match(/vimeo\.com\/(?:video\/|)(\d+)/);
    return (match && match[1]) ? match[1] : null;
  };

  const getEmbedUrl = (url: string) => {
    if (isYouTube(url)) {
      const id = getYouTubeId(url);
      return id ? `https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0&modestbranding=1` : url;
    }
    if (isVimeo(url)) {
      const id = getVimeoId(url);
      return id ? `https://player.vimeo.com/video/${id}?autoplay=1&badge=0&autopause=0&player_id=0&app_id=58479` : url;
    }
    return url;
  };

  const toggleFullscreen = (id: string) => {
    const el = document.getElementById(`container-${id}`);
    if (el) {
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else {
        el.requestFullscreen().catch(err => console.error(err));
      }
    }
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-12 lg:gap-20 items-start">
      {projects.map((project) => (
        <div key={project.id} className="flex flex-col reveal">
          <div 
            id={`container-${project.id}`}
            className="relative w-full overflow-hidden rounded-[48px] border border-white/50 shadow-2xl bg-slate-900 group transition-all duration-700 glass-card"
            style={{ 
              aspectRatio: project.id === 'snap-story' ? '9 / 16' : '16 / 9',
              maxHeight: project.id === 'snap-story' ? '800px' : 'none'
            }}
          >
            {playingId === project.id && project.videoUrl ? (
              <div className="absolute inset-0 w-full h-full bg-black z-10">
                {isYouTube(project.videoUrl) || isVimeo(project.videoUrl) ? (
                  <iframe
                    className="absolute inset-0 w-full h-full"
                    src={getEmbedUrl(project.videoUrl)}
                    title={project.title}
                    frameBorder="0"
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share; fullscreen"
                    referrerPolicy="strict-origin-when-cross-origin"
                    allowFullScreen
                  ></iframe>
                ) : (
                  <video 
                    src={project.videoUrl} 
                    autoPlay 
                    controls 
                    playsInline
                    className="absolute inset-0 w-full h-full object-cover"
                  />
                )}

                <div className="absolute top-4 left-4 right-4 z-20 flex justify-between items-center pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                  <div className="flex gap-1.5 pointer-events-auto">
                    <button 
                      onClick={() => setPlayingId(null)}
                      className="bg-black/40 hover:bg-black/80 backdrop-blur-md text-white text-[9px] font-black px-4 py-2 rounded-full transition-all border border-white/10 uppercase tracking-[0.3em]"
                    >
                      Close
                    </button>
                    <button 
                      onClick={() => toggleFullscreen(project.id)}
                      className="bg-black/40 hover:bg-black/80 backdrop-blur-md text-white text-[9px] font-black px-4 py-2 rounded-full transition-all border border-white/10 uppercase tracking-[0.3em]"
                    >
                      Full
                    </button>
                  </div>
                </div>
              </div>
            ) : (
              <div 
                className="absolute inset-0 w-full h-full cursor-pointer overflow-hidden bg-slate-200"
                onClick={() => setPlayingId(project.id)}
              >
                 {/* Image or AI Placeholder */}
                <img 
                  src={project.placeholderImg} 
                  alt={project.title} 
                  className="w-full h-full object-cover opacity-90 group-hover:opacity-30 transition-all duration-1000 group-hover:scale-110" 
                  onError={(e) => {
                    // Fallback if image fails
                    e.currentTarget.style.display = 'none';
                  }}
                />

                {/* Generation Indicator */}
                {project.placeholderImg.includes('unsplash') && project.genAiPrompt && (
                   <div className="absolute top-4 right-4 bg-black/30 backdrop-blur-md text-white text-[10px] font-bold px-4 py-2 rounded-full uppercase tracking-widest animate-pulse border border-white/20">
                     Generating AI Cover...
                   </div>
                )}

                <div className="absolute inset-0 flex items-center justify-center z-20">
                  <div className="w-24 h-24 md:w-28 md:h-28 bg-white/10 backdrop-blur-3xl border border-white/30 rounded-full flex items-center justify-center group-hover:scale-110 group-hover:bg-sky-500 transition-all duration-500 shadow-2xl">
                    <svg className="w-10 h-10 md:w-12 md:h-12 text-white translate-x-1" fill="currentColor" viewBox="0 0 24 24">
                      <path d="M8 5v14l11-7z" />
                    </svg>
                  </div>
                </div>
              </div>
            )}
          </div>

          <div className="px-4 mt-12">
            <div className="flex items-center gap-6 mb-10">
              <span className="text-xs font-black text-sky-500 tracking-[0.3em] uppercase bg-sky-50 px-5 py-2 rounded-xl border border-sky-100">
                {project.category}
              </span>
              <div className="h-[1px] flex-1 bg-slate-200/50"></div>
            </div>
            <h3 className="text-5xl md:text-6xl font-black font-heading text-slate-900 mb-6 tracking-wide">{project.title}</h3>
            <p className="text-slate-500 text-2xl font-light leading-relaxed mb-10 tracking-wide">{project.description}</p>
            <div className="flex flex-wrap gap-4 mb-10">
              {project.tech.map(t => (
                <span key={t} className="px-6 py-3 rounded-2xl border border-white glass-card text-xs font-bold text-slate-500 uppercase tracking-[0.2em] shadow-sm">
                  {t}
                </span>
              ))}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { About } from './components/About';
import { SkillsSection } from './components/SkillsSection';
import { Projects } from './components/Projects';
import { EducationSection } from './components/EducationSection';
import { ExperienceSection } from './components/ExperienceSection';
import { Footer } from './components/Footer';
import { Project, Education, Experience } from './types';

const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState('home');

  // Initial Data
  const initialProjectsData: Project[] = [
    {
      id: "learning-synapse",
      title: "SYNAPSE",
      category: "Learning Engine",
      description: "A recursive learning engine designed to map conceptual DNA through AI-driven content transformation.",
      points: [
        "Visualized complex information structures using cognitive load theory.",
        "Engineered an interface for deep hierarchical knowledge mapping."
      ],
      liveDemo: "https://www.linkedin.com/in/sijie-w-2020b738b",
      videoUrl: "https://vimeo.com/1156036453",
      tech: ["Information Design", "AI Integration", "UX Architecture"],
      placeholderImg: "https://images.unsplash.com/photo-1620641788421-7a1c342ea42e?q=80&w=1200&auto=format&fit=crop",
      // Updated Promot for more "Tech/Sci-Fi" feel
      genAiPrompt: "Abstract 3d isometric visualization of a digital learning engine, glowing cybernetic DNA strands connecting data blocks, deep cyan and neon purple aesthetic, futuristic schematic overlays, highly detailed, 8k octane render, technology background"
    },
    {
      id: "snap-story",
      title: "SnapStory",
      category: "ESL/EFL Acquisition",
      description: "A magical world for kids aged 6-12 where real-world photos are transformed into interactive stories for ESL and EFL learners.",
      points: [
        "Gamified vocabulary acquisition for non-native speakers through contextualized visual inputs.",
        "Designed child-centric UI with instructional scaffolding to lower cognitive barriers in language learning."
      ],
      liveDemo: "https://www.linkedin.com/in/sijie-w-2020b738b",
      videoUrl: "https://vimeo.com/1156035200",
      tech: ["ESL/EFL Pedagogy", "K-12 Tech", "Interactive Storytelling"],
      placeholderImg: "https://images.unsplash.com/photo-1549240923-93a2e080e653?q=80&w=1200&auto=format&fit=crop",
      // Cute Koala prompt (kept as user liked it)
      genAiPrompt: "A cute fluffy cartoon koala sitting on a cloud reading a magical glowing book, bright vibrant blue sky background, disney pixar style 3d render, soft lighting, cheerful, colorful, high quality"
    }
  ];

  const [projectsData, setProjectsData] = useState<Project[]>(initialProjectsData);
  const hasGeneratedRef = useRef(false);

  // Generate Images with Gemini
  useEffect(() => {
    const generateImages = async () => {
      if (hasGeneratedRef.current) return;
      hasGeneratedRef.current = true;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const updatedProjects = [...projectsData];
      let hasUpdates = false;

      for (let i = 0; i < updatedProjects.length; i++) {
        const project = updatedProjects[i];
        if (project.genAiPrompt) {
          try {
            console.log(`Generating cover for ${project.title}...`);
            const response = await ai.models.generateContent({
              model: 'gemini-2.5-flash-image',
              contents: {
                parts: [{ text: project.genAiPrompt }]
              }
            });

            // Extract image from response
            const parts = response.candidates?.[0]?.content?.parts;
            if (parts) {
              for (const part of parts) {
                if (part.inlineData && part.inlineData.data) {
                  updatedProjects[i] = {
                    ...project,
                    placeholderImg: `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`
                  };
                  hasUpdates = true;
                }
              }
            }
          } catch (error) {
            console.error(`Failed to generate image for ${project.title}`, error);
          }
        }
      }

      if (hasUpdates) {
        setProjectsData(updatedProjects);
      }
    };

    generateImages();
  }, []); // Run once on mount

  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          setActiveSection(entry.target.id);
        }
      });
    }, { threshold: 0.3, rootMargin: '-80px 0px -20% 0px' });

    const sections = document.querySelectorAll('section');
    sections.forEach(el => observer.observe(el));

    const revealObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
